//! Which sorts a value carries, and whether a binder sort's universe is
//! generated by ground terms (2026-09-23 hunt, D1). See `carried_fields.rs`
//! for the elements such values hold.

use ay_core::kani_compat::{DetHashMap as HashMap, DetHashSet as HashSet};
use ay_core::{Sort, TermData, TermId};

use super::super::Executor;

impl Executor {
    /// Scan `assertions` for everything that can put an element into the
    /// universe of one of `sorts` other than a ground term of that sort, and
    /// return the ground datatype terms whose values carry such elements in
    /// their fields (the caller must name those elements, see
    /// [`Self::carried_binder_field_terms`]).
    ///
    /// `None` — the universe is not generated by ground terms — when:
    /// - a function APPLICATION (an `App` with at least one argument) returns
    ///   one of `sorts`, other than a selector reading a field of a ground
    ///   datatype term. Such a symbol can generate domain elements beyond the
    ///   ground constants, making the Herbrand universe potentially infinite;
    /// - a term whose sort carries one of `sorts` (see
    ///   [`Self::sort_carries_any_of`]) mentions a bound variable: every
    ///   instance could hold an element no ground term names;
    /// - such a term is not a datatype (an array or sequence over the sort),
    ///   so its value cannot be followed field by field;
    /// - a quantifier is nested below a top-level one (its binders are not
    ///   tracked here).
    ///
    /// Equality / disequality are Boolean-valued, never return an uninterpreted
    /// sort, so they are naturally excluded by the result-sort test. A bare
    /// constant declared as (declare-fun a () U) is an `App` with ZERO args (or a
    /// `Var`/`Const`) and is correctly NOT counted.
    pub(in crate::executor) fn binder_universe_carriers(
        &self,
        assertions: &[TermId],
        sorts: &HashSet<Sort>,
    ) -> Option<Vec<TermId>> {
        let selectors: HashSet<&str> = self
            .ctx
            .ctor_selectors_iter()
            .flat_map(|(_, sels)| sels.iter().map(String::as_str))
            .collect();
        let mut carries: HashMap<Sort, bool> = HashMap::default();
        let mut carriers: Vec<TermId> = Vec::new();
        for &assertion in assertions {
            let (root, bound): (TermId, Vec<String>) = match self.ctx.terms.get(assertion) {
                TermData::Forall(vars, body, _) | TermData::Exists(vars, body, _) => {
                    (*body, vars.iter().map(|(n, _)| n.clone()).collect())
                }
                _ => (assertion, Vec::new()),
            };
            let mut mentions: HashMap<TermId, bool> = HashMap::default();
            let mut visited: HashSet<TermId> = HashSet::default();
            let mut stack: Vec<TermId> = vec![root];
            while let Some(t) = stack.pop() {
                if !visited.insert(t) {
                    continue;
                }
                let sort = self.ctx.terms.sort(t);
                if let TermData::App(sym, args) = self.ctx.terms.get(t) {
                    if !args.is_empty() && sorts.contains(sort) {
                        let ground_selector = args.len() == 1
                            && selectors.contains(sym.name())
                            && self
                                .declared_datatype_name(self.ctx.terms.sort(args[0]))
                                .is_some()
                            && !self.term_mentions_names(args[0], &bound, &mut mentions);
                        if !ground_selector {
                            return None;
                        }
                    }
                }
                let carrying = match carries.get(sort) {
                    Some(&known) => known,
                    None => {
                        let known = self.sort_carries_any_of(sort, sorts);
                        carries.insert(sort.clone(), known);
                        known
                    }
                };
                if carrying {
                    if self.declared_datatype_name(sort).is_none()
                        || self.term_mentions_names(t, &bound, &mut mentions)
                    {
                        return None;
                    }
                    if !carriers.contains(&t) {
                        carriers.push(t);
                    }
                }
                match self.ctx.terms.get(t) {
                    TermData::App(_, args) => stack.extend(args.iter().copied()),
                    TermData::Not(inner) => stack.push(*inner),
                    TermData::Ite(c, a, b) => {
                        stack.push(*c);
                        stack.push(*a);
                        stack.push(*b);
                    }
                    TermData::Let(bindings, body) => {
                        for (_, v) in bindings {
                            stack.push(*v);
                        }
                        stack.push(*body);
                    }
                    TermData::Forall(..) | TermData::Exists(..) => return None,
                    _ => {}
                }
            }
        }
        Some(carriers)
    }

    /// Whether the ground terms of `assertions` generate every universe of
    /// `sorts` on their own: no generator and no datatype value carrying one.
    pub(in crate::executor) fn binder_universe_ground_only(
        &self,
        assertions: &[TermId],
        sorts: &HashSet<Sort>,
    ) -> bool {
        self.binder_universe_carriers(assertions, sorts)
            .is_some_and(|carriers| carriers.is_empty())
    }

    /// Whether `t` mentions a variable named in `names` (memoized in `memo`
    /// for one fixed `names`). Binding forms below `t` answer `true`: their
    /// scoping is not tracked here, and `true` only ever declines.
    fn term_mentions_names(
        &self,
        t: TermId,
        names: &[String],
        memo: &mut HashMap<TermId, bool>,
    ) -> bool {
        if names.is_empty() {
            return false;
        }
        if let Some(&known) = memo.get(&t) {
            return known;
        }
        let mentions = match self.ctx.terms.get(t) {
            TermData::Var(name, _) => names.iter().any(|n| n == name),
            TermData::App(_, args) => args
                .iter()
                .any(|&a| self.term_mentions_names(a, names, memo)),
            TermData::Not(inner) => self.term_mentions_names(*inner, names, memo),
            TermData::Ite(c, a, b) => {
                self.term_mentions_names(*c, names, memo)
                    || self.term_mentions_names(*a, names, memo)
                    || self.term_mentions_names(*b, names, memo)
            }
            TermData::Const(_) => false,
            _ => true,
        };
        memo.insert(t, mentions);
        mentions
    }

    /// The declared datatype behind `sort`: a `Sort::Datatype`, or — on the
    /// eager lowering paths, which spell a declared datatype as an
    /// uninterpreted sort — a `Sort::Uninterpreted` naming one.
    pub(in crate::executor) fn declared_datatype_name<'s>(
        &self,
        sort: &'s Sort,
    ) -> Option<&'s str> {
        match sort {
            Sort::Datatype(dt) => Some(dt.name.as_str()),
            Sort::Uninterpreted(name) if self.ctx.datatype_constructors(name).is_some() => {
                Some(name.as_str())
            }
            _ => None,
        }
    }

    /// An uninterpreted sort that is not a datatype in disguise: its
    /// universe is whatever the ground terms and the model make it.
    pub(in crate::executor) fn is_plain_uninterpreted_sort(&self, sort: &Sort) -> bool {
        matches!(sort, Sort::Uninterpreted(name) if self.ctx.datatype_constructors(name).is_none())
    }

    /// Whether a value of `sort` holds, strictly inside it, a value of one of
    /// `targets`: a datatype with a constructor field of (or carrying) that
    /// sort, or an array or sequence over it. Such a value puts elements into
    /// the target's universe that no term of the target sort need denote —
    /// `(declare-datatype W ((w (g U)) (w2)))` gives every `w`-value its own
    /// `U` element — so a finite-universe argument over the target sort that
    /// enumerates only the target's ground terms is incomplete.
    pub(in crate::executor) fn sort_carries_any_of(
        &self,
        sort: &Sort,
        targets: &HashSet<Sort>,
    ) -> bool {
        let mut expanded: HashSet<String> = HashSet::default();
        let mut stack = self.value_component_sorts(sort, &mut expanded);
        while let Some(component) = stack.pop() {
            if targets.contains(&component) {
                return true;
            }
            stack.extend(self.value_component_sorts(&component, &mut expanded));
        }
        false
    }

    /// The sorts of the values held directly inside a value of `sort`. Each
    /// datatype is expanded once (`expanded`), so recursive datatypes end.
    fn value_component_sorts(&self, sort: &Sort, expanded: &mut HashSet<String>) -> Vec<Sort> {
        match sort {
            Sort::Array(array) => vec![array.index_sort.clone(), array.element_sort.clone()],
            Sort::Seq(element) => vec![(**element).clone()],
            _ => {
                let Some(name) = self.declared_datatype_name(sort) else {
                    return Vec::new();
                };
                if !expanded.insert(name.to_string()) {
                    return Vec::new();
                }
                match self.ctx.datatype_constructors(name) {
                    Some(constructors) => constructors
                        .iter()
                        .filter_map(|c| self.ctx.constructor_selector_info(c))
                        .flat_map(|fields| fields.iter().map(|(_, s)| s.clone()))
                        .collect(),
                    None => match sort {
                        Sort::Datatype(dt) => dt
                            .constructors
                            .iter()
                            .flat_map(|c| c.fields.iter().map(|f| f.sort.clone()))
                            .collect(),
                        _ => Vec::new(),
                    },
                }
            }
        }
    }
}
